31|  // player stays a controlled view over them. State starts at the server
32|  // defaults so hydration matches, then a mount effect applies stored
33|  // prefs (parsed once) to volume, muted, and style via prefsRef.
34|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
