48|  routeRef.current = routeSceneId;
49|  const sessionRef = useRef<MusicSession | null>(null);
50|  const observedRef = useRef<string | null>(null);
51|
52|  // The one bridge into the session: builds the context (clock, rng,
53|  // scene signals) and mirrors the view and a style change to state.
