1|"use client";
2|
3|import { useEffect, useMemo, useRef, useState } from "react";
4|import { useRouter } from "next/navigation";
5|import { buildNavIndex, navReducer } from "@/core/reader";
6|import type { NavAction, SceneView } from "@/core/reader";
7|import { PictureSlot, usePictureScene } from "../picture-panel";
8|
9|export interface ChapterJump {
10|  ch: number;
11|  title: string;
12|  firstSceneId: string;
13|}
14|
15|// One-shot entry intent: set just before pushing the previous scene
16|// route, so the new page opens on its last sub-page. Client memory only,
17|// never the URL, so prerendered pages stay static and a direct URL load
18|// always starts at page 0.
19|let enterAtEnd = false;
20|
21|// Set on every in-app scene push. The heading takes focus only when this
22|// is set, so first load shows no focus ring.
23|let hasNavigated = false;
24|
25|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
26|// Sub-page moves stay in client state; scene moves push a new route.
27|export function ScenePage({
28|  view,
29|  chapters,
30|  views,
31|  bookId,
32|  textVersion,
33|}: {
34|  view: SceneView;
35|  chapters: ChapterJump[];
36|  views: { sceneId: string; pages: number }[];
37|  bookId: string;
38|  textVersion: string;
39|}) {
40|  const pic = usePictureScene({ bookId, textVersion, sceneId: view.sceneId });
41|  const router = useRouter();
42|  const index = useMemo(() => buildNavIndex(views), [views]);
43|  const lastPage = view.pages.length - 1;
44|  const [page, setPage] = useState(() => {
45|    if (enterAtEnd) {
46|      enterAtEnd = false;
47|      return lastPage;
48|    }
49|    return 0;
50|  });
51|  const headingRef = useRef<HTMLHeadingElement>(null);
52|  const sub = view.pages[page] ?? view.pages[0];
53|  const atStart = view.prevSceneId === null && page === 0;
54|  const atBookEnd = view.nextSceneId === null && page === lastPage;
55|
56|  // Every pager move runs through navReducer; a new scene id means a
57|  // route push, a same-scene result means a client sub-page move.
58|  function move(action: NavAction) {
59|    pic.hidePopover();
60|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
61|    if (next.sceneId !== view.sceneId) {
62|      hasNavigated = true;
63|      if (next.page > 0) enterAtEnd = true;
64|      router.push(`/leer/${next.sceneId}`);
65|      return;
66|    }
67|    if (next.page !== page) {
68|      setPage(next.page);
69|      window.scrollTo(0, 0);
70|    }
71|  }
72|
73|  function goNext() {
74|    move({ kind: "next" });
75|  }
76|
77|  function goPrev() {
78|    move({ kind: "prev" });
79|  }
80|
81|  // Scene entry resets orientation; sub-page moves keep the heading.
82|  useEffect(() => {
83|    if (hasNavigated) headingRef.current?.focus();
84|    window.scrollTo(0, 0);
85|  }, [view.sceneId]);
86|
87|  useEffect(() => {
88|    const onKey = (event: KeyboardEvent) => {
89|      if (event.metaKey || event.ctrlKey || event.altKey) return;
90|      const target = event.target as HTMLElement | null;
91|      if (
92|        target &&
93|        (target.tagName === "INPUT" ||
94|          target.tagName === "SELECT" ||
95|          target.tagName === "TEXTAREA" ||
96|          target.isContentEditable)
97|      ) {
98|        return;
99|      }
100|      if (event.key === "ArrowRight") {
101|        event.preventDefault();
102|        goNext();
103|      } else if (event.key === "ArrowLeft") {
104|        event.preventDefault();
105|        goPrev();
106|      }
107|    };
108|    window.addEventListener("keydown", onKey);
109|    return () => window.removeEventListener("keydown", onKey);
110|  }, [page, view.sceneId, index, router]);
111|
112|  function jumpChapter(ch: number) {
113|    const found = chapters.find((c) => c.ch === ch);
114|    if (found && found.firstSceneId !== view.sceneId) move({ kind: "goto", sceneId: found.firstSceneId });
115|  }
116|
117|  return (
118|    <article aria-labelledby="scene-heading">
119|      <div className="scene-view" ref={pic.viewRef}>
120|        <p className="scene-progress">
121|          <span className="scene-progress-chapter">{`Chapter ${view.ch} · ${view.chapterTitle}`}</span>
122|          <span className="scene-progress-sep" aria-hidden="true">
123|            ·
124|          </span>
125|          <span>{`Scene ${view.k} of ${view.n}${view.pages.length > 1 ? ` · Page ${page + 1} of ${view.pages.length}` : ""}`}</span>
126|          <button
127|            type="button"
128|            className="picture-scene"
129|            onClick={pic.illustrateScene}
130|            aria-label="Picture scene"
131|          >
132|            Picture scene
133|          </button>
134|        </p>
135|        <h2 id="scene-heading" ref={headingRef} tabIndex={-1}>
136|          {view.title}
137|        </h2>
138|        <PictureSlot card={pic.card} onDismiss={pic.dismissCard} />
139|        {sub?.paragraphs.map((p) => (
140|          <p key={p.id} id={p.id} data-n={p.n}>
141|            {p.text}
142|          </p>
143|        ))}
144|        {pic.popover !== null ? (
145|          <button
146|            type="button"
147|            ref={pic.popRef}
148|            className="picture-float"
149|            style={{ top: pic.popover.top, left: pic.popover.left }}
150|            onClick={pic.illustratePassage}
151|            aria-label="Picture this"
152|          >
153|            Picture this
154|          </button>
155|        ) : null}
156|      </div>
157|      <nav className="scene-nav" aria-label="Scenes">
158|        <button type="button" onClick={goPrev} disabled={atStart} aria-label="Previous">
159|          Previous
160|        </button>
161|        <button type="button" onClick={goNext} disabled={atBookEnd} aria-label="Next">
162|          Next
163|        </button>
164|        <label className="scene-jump">
165|          Chapter
166|          <select value={view.ch} onChange={(e) => jumpChapter(Number(e.target.value))} aria-label="Chapter">
167|            {chapters.map((c) => (
168|              <option key={c.ch} value={c.ch}>
169|                {c.ch}. {c.title}
170|              </option>
171|            ))}
172|          </select>
173|        </label>
174|      </nav>
175|    </article>
176|  );
177|}

