122|  // cancels the pending fade and starts from current levels.
123|  requestPlayRef.current = (next: Track, durSec: number) => {
124|    const els = [firstRef.current, secondRef.current];
125|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
126|    const dstIdx = 1 - srcIdx;
127|    const srcEl = els[srcIdx];
